-- ----------------------------
-- Table structure for pss_bank_code
-- ----------------------------
DROP TABLE IF EXISTS `pss_bank_code`;
CREATE TABLE `pss_bank_code`  (
  `id` bigint(64) UNSIGNED NOT NULL AUTO_INCREMENT COMMENT '主键',
  `ref_district_code` varchar(6) CHARACTER SET utf8 COLLATE utf8_bin NULL DEFAULT NULL COMMENT '地区编号',
  `ref_city_code` varchar(6) CHARACTER SET utf8 COLLATE utf8_bin NULL DEFAULT NULL COMMENT '城市编号',
  `settle_bank_no` varchar(12) CHARACTER SET utf8 COLLATE utf8_bin NULL DEFAULT NULL COMMENT '清算行号所属直参行号',
  `bank_no` varchar(32) CHARACTER SET utf8 COLLATE utf8_bin NULL DEFAULT NULL COMMENT '参与行号码',
  `bank_name` varchar(255) CHARACTER SET utf8 COLLATE utf8_bin NULL DEFAULT NULL COMMENT '参与行名称',
  `status` int(3) NULL DEFAULT NULL COMMENT '状态（10-正常；-99-停用）',
  `memo1` varchar(255) CHARACTER SET utf8 COLLATE utf8_bin NULL DEFAULT NULL COMMENT '备用字段',
  `memo2` varchar(255) CHARACTER SET utf8 COLLATE utf8_bin NULL DEFAULT NULL COMMENT '备用字段',
  `memo3` varchar(255) CHARACTER SET utf8 COLLATE utf8_bin NULL DEFAULT NULL COMMENT '备用字段',
  `memo4` varchar(255) CHARACTER SET utf8 COLLATE utf8_bin NULL DEFAULT NULL COMMENT '备用字段',
  `memo5` varchar(255) CHARACTER SET utf8 COLLATE utf8_bin NULL DEFAULT NULL COMMENT '备用字段',
  `create_user` bigint(64) NULL DEFAULT NULL COMMENT '创建人',
  `create_name` varchar(255) CHARACTER SET utf8 COLLATE utf8_bin NULL DEFAULT NULL COMMENT '创建人名称',
  `create_time` datetime(0) NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_user` bigint(64) NULL DEFAULT NULL COMMENT '更新人',
  `update_name` varchar(255) CHARACTER SET utf8 COLLATE utf8_bin NULL DEFAULT NULL COMMENT '更新人名称',
  `update_time` timestamp(0) NULL DEFAULT NULL ON UPDATE CURRENT_TIMESTAMP(0) COMMENT '更新时间',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `idx_bank_no`(`bank_no`, `bank_name`) USING BTREE,
  INDEX `idx_city_code`(`ref_city_code`, `settle_bank_no`, `bank_no`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 740604 CHARACTER SET = utf8 COLLATE = utf8_bin COMMENT = '银行码表' ROW_FORMAT = Compact;

