-- ----------------------------
-- Table structure for pss_bank_card_info
-- ----------------------------
DROP TABLE IF EXISTS `pss_bank_card_info`;
CREATE TABLE `pss_bank_card_info`  (
  `id` bigint(20) UNSIGNED NOT NULL AUTO_INCREMENT COMMENT '主键',
  `bank_name_abb` varchar(255) CHARACTER SET utf8 COLLATE utf8_bin NULL DEFAULT NULL COMMENT '发卡行名称简称(对照总行信息表bank_name_abb)',
  `bank_name` varchar(255) CHARACTER SET utf8 COLLATE utf8_bin NULL DEFAULT NULL COMMENT '发卡行名称',
  `card_name` varchar(255) CHARACTER SET utf8 COLLATE utf8_bin NULL DEFAULT NULL COMMENT '卡名',
  `card_bin` varchar(32) CHARACTER SET utf8 COLLATE utf8_bin NULL DEFAULT NULL COMMENT '卡bin',
  `card_type` tinyint(4) NULL DEFAULT NULL COMMENT '卡种(1=借记卡;2=贷记卡;3=准贷记卡;4=预付费卡)',
  `card_case` varchar(32) CHARACTER SET utf8 COLLATE utf8_bin NULL DEFAULT NULL COMMENT '卡例子',
  `card_length` tinyint(4) NULL DEFAULT NULL COMMENT '卡长度',
  `agency_code` varchar(32) CHARACTER SET utf8 COLLATE utf8_bin NULL DEFAULT NULL COMMENT '机构代码',
  `status` tinyint(4) NOT NULL COMMENT '状态（10-正常；-99-停用）',
  `memo1` varchar(255) CHARACTER SET utf8 COLLATE utf8_bin NULL DEFAULT NULL COMMENT '备用字段',
  `memo2` varchar(255) CHARACTER SET utf8 COLLATE utf8_bin NULL DEFAULT NULL COMMENT '备用字段',
  `memo3` varchar(255) CHARACTER SET utf8 COLLATE utf8_bin NULL DEFAULT NULL COMMENT '备用字段',
  `memo4` varchar(255) CHARACTER SET utf8 COLLATE utf8_bin NULL DEFAULT NULL COMMENT '备用字段',
  `memo5` varchar(255) CHARACTER SET utf8 COLLATE utf8_bin NULL DEFAULT NULL COMMENT '备用字段',
  `create_user` varchar(64) CHARACTER SET utf8 COLLATE utf8_bin NULL DEFAULT NULL COMMENT '创建用户',
  `create_time` datetime(0) NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_user` varchar(64) CHARACTER SET utf8 COLLATE utf8_bin NULL DEFAULT NULL COMMENT '修改用户',
  `update_time` datetime(0) NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '修改时间',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `idx_card_bin`(`card_bin`, `status`, `card_case`) USING BTREE COMMENT '卡bin查询索引'
) ENGINE = InnoDB AUTO_INCREMENT = 9081 CHARACTER SET = utf8 COLLATE = utf8_bin COMMENT = '银行卡卡表信息' ROW_FORMAT = Compact;

